export const HOPS: Hop[] = [
  { from: 41, topicLink: 'تفتتح السورتان بـ«حم»، وتذكران القرآن العربي: «قرآنًا عربيًا لقوم يعلمون» في فصلت و«أوحينا إليك قرآنًا عربيًا» في الشورى. وتشتركان في آيات الخلق والأخلاق، وفي طبع الإنسان: «لا يسأم الإنسان من دعاء الخير» في فصلت و«فإن الإنسان كفور» في الشورى.', tail: [52, 54], head: [1, 4], src: [], note: 'تختم فصلت بسؤال «قل أرأيتم إن كان من عند الله ثم كفرتم به»، وبوعد «سنريهم آياتنا في الآفاق وفي أنفسهم»، وبأنهم في مرية من لقاء ربهم «ألا إنه بكل شيء محيط». وتبدأ الشورى بـ«حم عسق»، ثم «كذلك يوحي إليك وإلى الذين من قبلك الله العزيز الحكيم»، وله ما في السماوات وما في الأرض.' },
  { from: 42, topicLink: 'تذكر السورتان القرآن العربي: «أوحينا إليك قرآنًا عربيًا» في الشورى و«إنا جعلناه قرآنًا عربيًا» في الزخرف. وتشتركان في آيات الخلق والتوحيد والجزاء.', tail: [51, 53], head: [1, 4], src: [], shared: [['حكيم', 51, 4], ['جعلنه', 52, 3], ['الكتب', 52, 4]], note: 'تختم الشورى بأن الله لا يكلم بشرًا إلا وحيًا أو من وراء حجاب أو يرسل رسولًا «إنه علي حكيم»، وبأنه أوحى إليه روحًا من أمرنا: «ما كنت تدري ما الكتاب ولا الإيمان ولكن جعلناه نورًا». وتبدأ الزخرف بالقسم «والكتاب المبين»، ثم «إنا جعلناه قرآنًا عربيًا» وأنه في أم الكتاب «لعلي حكيم»، فتتكرر «جعلناه» و«الكتاب» و«حكيم».' },
  { from: 43, topicLink: 'تفتتح السورتان بـ«حم» وبالقسم نفسه «والكتاب المبين»، ثم بإنزال القرآن: «إنا جعلناه قرآنًا عربيًا» في الزخرف و«إنا أنزلناه في ليلة مباركة» في الدخان. وتذكران فرعون وقومه، والتوحيد، وجزاء المتقين والمجرمين.', tail: [85, 89], head: [1, 4], src: [], note: 'تختم الزخرف بأن عند الله علم الساعة وإليه ترجعون، وبقوله «يا رب إن هؤلاء قوم لا يؤمنون»، ثم بالأمر «فاصفح عنهم وقل سلام فسوف يعلمون». وتبدأ الدخان بـ«حم» والقسم «والكتاب المبين» كما بدأت الزخرف، ثم «إنا أنزلناه في ليلة مباركة إنا كنا منذرين».' },
  { from: 44, topicLink: 'تفتتح السورتان بـ«حم» وبالكتاب: «والكتاب المبين» في الدخان و«تنزيل الكتاب من الله العزيز الحكيم» في الجاثية. وتحكيان قول المنكرين للبعث: «فأتوا بآبائنا إن كنتم صادقين» في الدخان و«ائتوا بآبائنا إن كنتم صادقين» في الجاثية، وتشتركان في الجزاء: «ذلك هو الفوز العظيم» و«ذلك هو الفوز المبين».', tail: [56, 59], head: [1, 4], src: [], note: 'تختم الدخان بنعيم المتقين «فضلًا من ربك ذلك هو الفوز العظيم»، ثم «فإنما يسرناه بلسانك لعلهم يتذكرون» والأمر «فارتقب إنهم مرتقبون». وتبدأ الجاثية بـ«حم» و«تنزيل الكتاب من الله العزيز الحكيم»، ثم بآيات في السماوات والأرض وفي خلقهم وما يبث من دابة.' },
  { from: 45, topicLink: 'تفتتح السورتان بالآية نفسها بعد «حم»: «تنزيل الكتاب من الله العزيز الحكيم». وتشتركان في التوحيد والمكذبين والجزاء: «ومأواكم النار» في الجاثية و«ويوم يعرض الذين كفروا على النار» في الأحقاف.', tail: [35, 37], head: [1, 3], src: [], shared: [['السموت والارض', 37, 3], ['العزيز الحكيم', 37, 2]], note: 'تختم الجاثية بالذين اتخذوا آيات الله هزوًا «فاليوم لا يخرجون منها ولا هم يستعتبون»، ثم بالحمد لله رب السماوات ورب الأرض «وهو العزيز الحكيم». وتبدأ الأحقاف بـ«حم» و«تنزيل الكتاب من الله العزيز الحكيم»، ثم بأن الله ما خلق السماوات والأرض وما بينهما إلا بالحق وأجل مسمى، فتتكرر «العزيز الحكيم» و«السماوات والأرض».' },
  { from: 46, topicLink: 'تختم الأحقاف بعرض الذين كفروا على النار، وتبدأ محمد بأن الذين كفروا وصدوا عن سبيل الله أضل أعمالهم. وتشترك السورتان في القرآن («نفرًا من الجن يستمعون القرآن» و«أفلا يتدبرون القرآن») وفي جزاء الفريقين.', tail: [33, 35], head: [1, 3], src: [], shared: [['الذين كفروا', 34, 1]], note: 'تنتهي الأحقاف بعرض الذين كفروا على النار وبأمر النبي ﷺ بالصبر: «فهل يهلك إلا القوم الفاسقون». وتبدأ محمد بالذين كفروا وصدوا عن سبيل الله، ثم بالذين آمنوا بما نزل على محمد، فتتكرر «الذين كفروا».' },
  { from: 47, topicLink: 'تذكر السورتان الذين كفروا وصدوا عن سبيل الله أو عن المسجد الحرام، والمؤمنين وجزاءهم بالجنات. وينتقل الكلام من الأمر بالقتال والإنفاق في محمد إلى الفتح والسكينة في الفتح.', tail: [36, 38], head: [1, 3], src: [], note: 'تنتهي محمد بدعوة المؤمنين إلى الإنفاق في سبيل الله، وبقوله «وإن تتولوا يستبدل قومًا غيركم». وتبدأ الفتح بخطاب النبي ﷺ: «إنا فتحنا لك فتحًا مبينًا» ونصر عزيز.' },
  { from: 48, topicLink: 'تصف الفتح النبي ﷺ والذين معه أشداء على الكفار رحماء بينهم، وتفصّل الحجرات أدبهم معه ومع بعضهم. وتذكر السورتان الأعراب: المخلفين منهم في الفتح، والذين قالوا آمنا في الحجرات.', tail: [26, 29], head: [1, 3], src: [], shared: [['رسول الله', 29, 3], ['مغفره', 29, 3]], note: 'تختم الفتح بـ«محمد رسول الله والذين معه» ووعدهم مغفرة وأجرًا عظيمًا. وتبدأ الحجرات بنهي المؤمنين أن يتقدموا بين يدي الله ورسوله أو يرفعوا أصواتهم، ولمن يغض صوته عند رسول الله مغفرة وأجر عظيم.' },
  { from: 49, topicLink: 'ينتقل الكلام من أحكام المؤمنين في الحجرات إلى المكذبين بالبعث في ق. ويجمعهما علم الله: «والله يعلم ما في السماوات وما في الأرض» في الحجرات، و«قد علمنا ما تنقص الأرض منهم» في ق.', tail: [16, 18], head: [1, 4], src: [], note: 'تختم الحجرات بأن الله يعلم غيب السماوات والأرض وبصير بما يعملون. وتبدأ ق بالقسم بالقرآن المجيد، ثم بعجب الكافرين من منذر منهم وإنكارهم الرجوع بعد أن يكونوا ترابًا.' },
  { from: 50, topicLink: 'تفتتح السورتان بالقسم، وتذكران من الأمم المكذبة قوم نوح وعادًا وثمود وفرعون. وتتكرر آيات السماء والأرض، والبعث: «ذلك يوم الخروج» في ق و«وإن الدين لواقع» في الذاريات.', tail: [41, 45], head: [1, 4], src: [], note: 'تختم ق بيوم الخروج حين تشقق الأرض عنهم، وبأمر النبي ﷺ أن يذكّر بالقرآن من يخاف الوعيد. وتبدأ الذاريات بأقسام متتابعة: الذاريات والحاملات والجاريات والمقسمات.' },
  { from: 51, topicLink: 'تفتتح السورتان بأقسام، ثم تأتي في كل منهما «لواقع»: «وإن الدين لواقع» في الذاريات و«إن عذاب ربك لواقع» في الطور. ويتكرر الويل: «فويل للذين كفروا» في آخر الذاريات و«فويل يومئذ للمكذبين» في الطور.', tail: [56, 60], head: [1, 4], src: [], note: 'تختم الذاريات بأن الله خلق الجن والإنس ليعبدوه، ثم «فويل للذين كفروا من يومهم الذي يوعدون». وتبدأ الطور بأقسام: الطور وكتاب مسطور في رق منشور والبيت المعمور.' },
  { from: 52, topicLink: 'تنفي الطور أن يكون النبي ﷺ كاهنًا أو مجنونًا، وتنفي النجم أن يكون صاحبهم ضل أو غوى. وتفتتح السورتان بالقسم، وتختم الطور بالأمر بالتسبيح والنجم بالأمر بالسجود.', tail: [45, 49], head: [1, 4], src: [], note: 'تختم الطور بأمر النبي ﷺ بالصبر لحكم ربه وبالتسبيح «وإدبار النجوم». وتبدأ النجم بالقسم «والنجم إذا هوى»، ثم بأن صاحبهم ما ضل وما غوى وما ينطق عن الهوى.' },
  { from: 53, topicLink: 'تقترب خاتمة النجم من فاتحة القمر: «أزفت الآزفة» في النجم و«اقتربت الساعة» في القمر. وتذكر السورتان هلاك عاد وثمود وقوم نوح، وتذكران الوحي والقرآن.', tail: [58, 62], head: [1, 3], src: [], note: 'تختم النجم بالعجب من هذا الحديث وبالضحك وترك البكاء، ثم بالأمر: «فاسجدوا لله واعبدوا». وتبدأ القمر بـ«اقتربت الساعة وانشق القمر»، وبإعراضهم عن الآيات وقولهم «سحر مستمر».' },
  { from: 54, topicLink: 'في كل من السورتين آية تتكرر: «ولقد يسرنا القرآن للذكر فهل من مدكر» في القمر، و«فبأي آلاء ربكما تكذبان» في الرحمن. وتشتركان في القرآن وآيات الخلق وجزاء المجرمين والمتقين.', tail: [51, 55], head: [1, 4], src: [], note: 'تختم القمر بالمتقين في جنات ونهر «في مقعد صدق عند مليك مقتدر». وتبدأ الرحمن باسم «الرحمن» الذي علم القرآن وخلق الإنسان وعلمه البيان.' },
  { from: 55, topicLink: 'تقسم السورتان الناس في الجزاء: في الرحمن من خاف مقام ربه له جنتان ومن دونهما جنتان، وفي الواقعة السابقون وأصحاب اليمين وأصحاب الشمال. وتتشابه أوصاف النعيم في الموضعين: فاكهة وحور واتكاء على فرش.', tail: [74, 78], head: [1, 4], src: [], note: 'تختم الرحمن بنعيم الجنتين واتكاء أهلهما على رفرف خضر، ثم «تبارك اسم ربك ذي الجلال والإكرام». وتبدأ الواقعة بـ«إذا وقعت الواقعة» ثم برجّ الأرض.' },
  { from: 56, topicLink: 'تتصل السورتان بالتسبيح: آخر الواقعة أمر به وأول الحديد خبر عنه. وتشتركان في آيات الخلق، وفي القرآن والكتاب المنزل، وفي يوم القيامة.', tail: [92, 96], head: [1, 3], src: [], note: 'تختم الواقعة بالمكذبين الضالين ونزل من حميم، ثم «إن هذا لهو حق اليقين، فسبح باسم ربك العظيم». وتبدأ الحديد بـ«سبح لله ما في السماوات والأرض».' },
  { from: 57, topicLink: 'ينتقل الكلام من الإنفاق والإيمان في الحديد إلى أحكام الظهار والنجوى والمجالس في المجادلة. وتذكر الحديد المنافقين يوم يلتمسون النور، وتذكر المجادلة الذين اتخذوا أيمانهم جنة ويوم يبعثهم الله جميعًا.', tail: [27, 29], head: [1, 4], src: [], note: 'تختم الحديد بوعد المؤمنين كفلين من رحمته، وبأن الفضل بيد الله يؤتيه من يشاء. وتبدأ المجادلة بـ«قد سمع الله قول التي تجادلك في زوجها»، ثم بحكم الذين يظاهرون من نسائهم.' },
  { from: 58, topicLink: 'في آخر المجادلة «كتب الله لأغلبن أنا ورسلي»، وفي أول الحشر إخراج الذين كفروا من أهل الكتاب من ديارهم. وتتكرر «هم المفلحون»: حزب الله في المجادلة، ومن يوق شح نفسه في الحشر.', tail: [20, 22], head: [1, 4], src: [], shared: [['الله ورسوله', 20, 4]], note: 'تختم المجادلة بأن الذين يحادون الله ورسوله في الأذلين، وبأن حزب الله هم المفلحون. وتبدأ الحشر بالتسبيح، ثم بإخراج الذين كفروا من أهل الكتاب من ديارهم «بأنهم شاقوا الله ورسوله».' },
  { from: 59, topicLink: 'تفصل السورتان بين المؤمنين وعدوهم: في الحشر الذين كفروا من أهل الكتاب والذين نافقوا، وفي الممتحنة النهي عن موالاة من يخرجون الرسول والمؤمنين. ويأتي التوحيد في خاتمة الحشر، وفي الممتحنة قول إبراهيم والذين معه «حتى تؤمنوا بالله وحده».', tail: [22, 24], head: [1, 4], src: [], note: 'تختم الحشر بأسماء الله: «هو الله الذي لا إله إلا هو» الملك القدوس السلام، له الأسماء الحسنى. وتبدأ الممتحنة بنهي المؤمنين أن يتخذوا عدو الله وعدوهم أولياء، ثم بأسوة إبراهيم والذين معه إذ تبرؤوا من قومهم.' },
  { from: 60, topicLink: 'تخاطب السورتان المؤمنين بـ«يا أيها الذين آمنوا» في أولهما وآخرهما. وفي الممتحنة أسوة إبراهيم والذين معه، وفي الصف موسى وعيسى ابن مريم مع قومهما.', tail: [11, 13], head: [1, 4], src: [], shared: [['يايها الذين ءامنوا', 13, 2]], note: 'تختم الممتحنة بنداء «يا أيها الذين آمنوا لا تتولوا قومًا غضب الله عليهم». وتبدأ الصف بالتسبيح، ثم بالنداء نفسه: «يا أيها الذين آمنوا لم تقولون ما لا تفعلون».' },
  { from: 61, topicLink: 'تفتتح السورتان بالتسبيح بلفظ متقارب: «سبح لله ما في السماوات وما في الأرض» و«يسبح لله ما في السماوات وما في الأرض». وتذكر الصف عيسى مبشرًا برسول يأتي من بعده، وتذكر الجمعة رسولًا بعثه الله في الأميين، وتذكر كلتاهما التجارة.', tail: [10, 14], head: [1, 4], src: [], note: 'تختم الصف بدعوة المؤمنين إلى تجارة تنجيهم: الإيمان بالله ورسوله والجهاد، وبقول الحواريين «نحن أنصار الله». وتبدأ الجمعة بالتسبيح، ثم بأن الله بعث في الأميين رسولًا منهم يتلو عليهم آياته.' },
  { from: 62, topicLink: 'يتصل ذكر الله والمال بين السورتين: في الجمعة «فاسعوا إلى ذكر الله وذروا البيع»، وفي المنافقون «لا تلهكم أموالكم ولا أولادكم عن ذكر الله». وتشتركان في خطاب النبي ﷺ وذكر المكذبين.', tail: [8, 11], head: [1, 2], src: [], note: 'تنتهي الجمعة بالذين رأوا تجارة أو لهوًا فانفضوا إليها «وتركوك قائمًا». وتبدأ المنافقون بالمنافقين إذا جاؤوا النبي ﷺ قالوا «نشهد إنك لرسول الله»، والله يشهد إنهم لكاذبون.' },
  { from: 63, topicLink: 'يعود في التغابن ما في المنافقون من فتنة المال والولد والأمر بالإنفاق: «إنما أموالكم وأولادكم فتنة» و«وأنفقوا خيرًا لأنفسكم». وتشتركان في ذكر الذين كفروا.', tail: [9, 11], head: [1, 2], src: [], shared: [['بما تعملون', 11, 2]], note: 'تختم المنافقون بالنهي عن أن تلهي الأموال والأولاد عن ذكر الله، وبأن الله «خبير بما تعملون». وتبدأ التغابن بتسبيح ما في السماوات والأرض لله، وفيها «والله بما تعملون بصير»، فتتكرر «بما تعملون».' },
  { from: 64, topicLink: 'تذكر التغابن الأزواج والأولاد والأموال، وتأتي الطلاق بأحكام الطلاق والعدة والسكنى والنفقة. ويتكرر في السورتين الأمر بتقوى الله والإنفاق، وجزاء من يؤمن بالله ويعمل صالحًا: «يكفر عنه سيئاته» و«جنات تجري من تحتها الأنهار».', tail: [16, 18], head: [1, 1], src: [], note: 'تنتهي التغابن بالأمر «فاتقوا الله ما استطعتم» وبالإنفاق والقرض الحسن. وتبدأ الطلاق بخطاب النبي ﷺ في طلاق النساء وعدتهن، وفيها «واتقوا الله ربكم».' },
  { from: 65, topicLink: 'تفتتح السورتان بخطاب «يا أيها النبي» في شأن الأزواج: الطلاق والعدة في الطلاق، وتحريم ما أحل الله له وما أسره إلى بعض أزواجه في التحريم. وفي كلتيهما عاقبة الكفر: قرية عتت عن أمر ربها في الطلاق، وامرأتا نوح ولوط في التحريم.', tail: [10, 12], head: [1, 2], src: [], note: 'تختم الطلاق بالذكر الذي أنزله الله ورسول يتلو آياته، وبخلق سبع سماوات ومن الأرض مثلهن. وتبدأ التحريم بخطاب النبي ﷺ «لم تحرم ما أحل الله لك» وبتحلة الأيمان.' },
  { from: 66, topicLink: 'ينتقل الكلام من أمثلة الكفر والإيمان في التحريم إلى ابتلاء الناس «أيكم أحسن عملًا» في الملك. وتشترك السورتان في النار وأهلها وفي الذين كفروا.', tail: [8, 12], head: [1, 2], src: [], shared: [['علي كل شيء قدير', 8, 1]], note: 'تختم التحريم بمثلين: امرأتا نوح ولوط للذين كفروا، وامرأة فرعون ومريم ابنة عمران للذين آمنوا، وقبلهما قول المؤمنين «إنك على كل شيء قدير». وتبدأ الملك بـ«تبارك الذي بيده الملك وهو على كل شيء قدير»، ثم بخلق الموت والحياة للابتلاء.' },
  { from: 67, topicLink: 'يتصل الوعيد «فستعلمون» في آخر الملك بقوله في القلم «فستبصر ويبصرون». وتشترك السورتان في المكذبين ويوم القيامة والابتلاء: «ليبلوكم» في الملك و«بلوناهم» في القلم.', tail: [28, 30], head: [1, 4], src: [], note: 'تختم الملك بأوامر «قل» للنبي ﷺ، ومنها «فستعلمون من هو في ضلال مبين» و«فمن يأتيكم بماء معين». وتبدأ القلم بالقسم «ن والقلم وما يسطرون»، ثم بأن النبي ﷺ ليس بمجنون وأن له أجرًا غير ممنون وأنه على خلق عظيم.' },
  { from: 68, topicLink: 'تنفي السورتان قول الكافرين في النبي ﷺ والقرآن: «إنه لمجنون» في القلم، و«وما هو بقول شاعر» و«ولا بقول كاهن» في الحاقة، وتختمان بالقرآن: «ذكر للعالمين» و«لتذكرة للمتقين». وتشتركان في القسم ويوم القيامة والمكذبين.', tail: [48, 52], head: [1, 4], src: [], note: 'تختم القلم بأمر النبي ﷺ بالصبر لحكم ربه، وبقول الكافرين «إنه لمجنون»، وبأنه «ذكر للعالمين». وتبدأ الحاقة بالسؤال عن الحاقة ثم بتكذيب ثمود وعاد بالقارعة.' },
  { from: 69, topicLink: 'يتصل يوم القيامة: «فيومئذ وقعت الواقعة» في الحاقة، و«سأل سائل بعذاب واقع» في المعارج. وفي كلتيهما القسم «فلا أقسم» والجزاء بالجنة والنار وذكر الكافرين.', tail: [48, 52], head: [1, 4], src: [], note: 'تختم الحاقة بأن القرآن تذكرة للمتقين وحسرة على الكافرين، وبالأمر «فسبح باسم ربك العظيم». وتبدأ المعارج بسائل سأل بعذاب واقع «للكافرين ليس له دافع»، من الله ذي المعارج «تعرج الملائكة والروح إليه».' },
  { from: 70, topicLink: 'تذكر المعارج «الذين كفروا قبلك مهطعين» والقدرة على أن يُبدل خير منهم، وتعرض نوح قومًا عصوا نبيهم فأغرقوا. وتشتركان في الخروج من الأرض: «يخرجون من الأجداث» في المعارج و«يعيدكم فيها ويخرجكم إخراجًا» في نوح، وفي الجزاء.', tail: [40, 44], head: [1, 2], src: [], note: 'تختم المعارج بالقسم برب المشارق والمغارب «إنا لقادرون على أن نبدل خيرًا منهم»، ثم بيوم يخرجون من الأجداث سراعًا «ذلك اليوم الذي كانوا يوعدون». وتبدأ نوح بإرسال نوح إلى قومه أن ينذرهم من قبل أن يأتيهم عذاب أليم.' },
  { from: 71, topicLink: 'تعرض نوح قومًا دعاهم نبيهم ليلًا ونهارًا فعصوه وقالوا «لا تذرن آلهتكم»، وتعرض الجن نفرًا من الجن استمعوا القرآن فآمنوا به. ويتصل التوحيد: «أن اعبدوا الله» في نوح، و«ولن نشرك بربنا أحدًا» في الجن، ويتصل الجزاء بالنار.', tail: [25, 28], head: [1, 2], src: [], note: 'تختم نوح بدعاء نوح «لا تذر على الأرض من الكافرين ديارًا»، وبدعائه بالمغفرة له ولوالديه وللمؤمنين والمؤمنات. وتبدأ الجن بنفر من الجن استمعوا فقالوا «إنا سمعنا قرآنًا عجبًا» «فآمنا به ولن نشرك بربنا أحدًا».' },
  { from: 72, topicLink: 'تأمر الجن النبي ﷺ بـ«قل» أن يعلن «إنما أدعو ربي ولا أشرك به أحدًا»، وتخاطبه المزمل بقيام الليل والترتيل والصبر. وتشتركان في القرآن: سمعه الجن في الأولى، ويُرتل ويُلقى «قولًا ثقيلًا» في الثانية، وفي التوحيد: «لا إله إلا هو فاتخذه وكيلًا».', tail: [25, 28], head: [1, 4], src: [], note: 'تختم الجن بأن الله عالم الغيب فلا يظهر على غيبه أحدًا إلا من ارتضى من رسول، «ليعلم أن قد أبلغوا رسالات ربهم». وتبدأ المزمل بنداء «يا أيها المزمل» وأمره بقيام الليل وترتيل القرآن.' },
  { from: 73, topicLink: 'تفتتح السورتان بنداء النبي ﷺ «يا أيها المزمل» و«يا أيها المدثر» ثم الأمر «قم». وتشتركان في التذكرة: «إن هذه تذكرة» في المزمل و«كلا إنه تذكرة» في المدثر، وفي يوم القيامة والمكذبين.', tail: [18, 20], head: [1, 4], src: [], note: 'تختم المزمل بأن «هذه تذكرة»، وبقوله «فاقرءوا ما تيسر من القرآن» والأمر بالصلاة والزكاة والقرض الحسن والاستغفار. وتبدأ المدثر بنداء «يا أيها المدثر» وأمره «قم فأنذر وربك فكبر وثيابك فطهر».' },
  { from: 74, topicLink: 'يتصل إنكار الآخرة: «لا يخافون الآخرة» في آخر المدثر، و«أيحسب الإنسان ألن نجمع عظامه» في أول القيامة. ويتكرر التركيب «بل يريد»: «بل يريد كل امرئ منهم» في المدثر و«بل يريد الإنسان ليفجر أمامه» في القيامة، وتشترك السورتان في القسم ويوم القيامة والجزاء.', tail: [52, 56], head: [1, 4], src: [], note: 'تختم المدثر بأن كل امرئ منهم يريد أن يؤتى صحفًا منشرة، وبأنهم «لا يخافون الآخرة»، ثم «كلا إنه تذكرة» وأن الله «أهل التقوى وأهل المغفرة». وتبدأ القيامة بالقسم بيوم القيامة وبالنفس اللوامة، ثم بسؤال «أيحسب الإنسان ألن نجمع عظامه».' },
  { from: 75, topicLink: 'تختم القيامة بخلق الإنسان من نطفة وبعده «أليس ذلك بقادر على أن يحيي الموتى»، وتبدأ الإنسان بخلقه من نطفة «نبتليه». وتشترك السورتان في طبع الإنسان والجزاء، وفي خطاب النبي ﷺ في القرآن: «لا تحرك به لسانك» و«إنا نحن نزلنا عليك القرآن تنزيلًا».', tail: [36, 40], head: [1, 3], src: [], shared: [['الانسن', 36, 1], ['نطفه', 37, 2]], note: 'تختم القيامة بسؤالين: «أيحسب الإنسان أن يترك سدى» و«أليس ذلك بقادر على أن يحيي الموتى»، وبينهما خلقه من نطفة ثم علقة. وتبدأ الإنسان بـ«هل أتى على الإنسان حين من الدهر» وبخلقه «من نطفة أمشاج نبتليه»، فتتكرر «الإنسان» و«نطفة».' },
  { from: 76, topicLink: 'تفصل الإنسان جزاء الأبرار وتختم بعذاب الظالمين، وتكرر المرسلات «ويل يومئذ للمكذبين» وتذكر المتقين «في ظلال وعيون». وتشتركان في خلق الإنسان من ماء: «من نطفة أمشاج» و«من ماء مهين»، وفي اليوم: «يومًا عبوسًا قمطريرًا» و«يوم الفصل».', tail: [28, 31], head: [1, 4], src: [], note: 'تختم الإنسان بأن «هذه تذكرة فمن شاء اتخذ إلى ربه سبيلًا»، وبأن الله يدخل من يشاء في رحمته «والظالمين أعد لهم عذابًا أليمًا». وتبدأ المرسلات بأقسام متتابعة: «والمرسلات عرفًا فالعاصفات عصفًا».' },
  { from: 77, topicLink: 'يتكرر في السورتين «يوم الفصل»: «هذا يوم الفصل جمعناكم والأولين» في المرسلات، و«إن يوم الفصل كان ميقاتًا» في النبأ. وتشتركان في المكذبين وآيات الخلق والجزاء.', tail: [46, 50], head: [1, 4], src: [], note: 'تختم المرسلات بالويل للمكذبين الذين إذا قيل لهم اركعوا لا يركعون، وبسؤال «فبأي حديث بعده يؤمنون». وتبدأ النبأ بسؤال آخر: «عم يتساءلون» عن النبأ العظيم الذي هم فيه مختلفون.' },
  { from: 78, topicLink: 'ينتقل الكلام من إنكار البعث وأدلته في النبأ إلى أقسام النازعات وسؤالهم عن الساعة. ويتكرر التكذيب (اختلافهم في النبأ، وفرعون في النازعات) وآيات الخلق ويوم القيامة والجزاء بالجنة والنار.', tail: [38, 40], head: [1, 4], src: [], note: 'تنتهي النبأ بيوم يقوم فيه الروح والملائكة صفًّا ويرى المرء ما قدمت يداه. وتبدأ النازعات بأقسام متتابعة.' },
  { from: 79, topicLink: 'تنتهي النازعات بالسؤال عن الساعة وتبدأ عبس بتوجيه النبي ﷺ وبالتذكرة. وتشترك السورتان في يوم القيامة (الطامة والصاخة) وفي آيات الخلق: السماء والأرض في النازعات، والطعام في عبس.', tail: [45, 46], head: [1, 4], src: [], note: 'تنتهي النازعات بأن النبي ﷺ منذر من يخشى الساعة. وتبدأ عبس بأعمى جاء يطلب التزكي والتذكر، فيتصل الإنذار بمن ينتفع بالتذكير.' },
  { from: 80, topicLink: 'ينتقل الكلام من الصاخة وحال الوجوه في عبس إلى أحداث يوم القيامة نفسه في التكوير، ثم يعود القرآن وحال النبي ﷺ بعد القسم.', tail: [38, 42], head: [1, 4], src: [], note: 'تختم عبس بوجوه مسفرة ضاحكة يومئذ ووجوه عليها غبرة. وتبدأ التكوير بعلامات ذلك اليوم: الشمس تكوّر والنجوم تنكدر والجبال تسيّر.' },
  { from: 81, topicLink: 'يتصل انكدار الكون في التكوير بانفطاره في الانفطار، وتتصل الصحف المنشورة بالكتبة الكرام.', tail: [26, 29], head: [1, 4], src: [], note: 'تنتهي التكوير بأن القرآن ذكر للعالمين وأن المشيئة لله. وتبدأ الانفطار بصيغة التكوير نفسها: «إذا» ثم أحداث كونية، السماء والكواكب والبحار والقبور.' },
  { from: 82, topicLink: 'بعد الانفطار وذكر الأبرار والفجار يأتي ويل المطففين، فينتقل الكلام من صلة الإنسان بربه إلى معاملته للناس، ويبقى كتاب الأعمال ومصير الأبرار والفجار.', tail: [17, 19], head: [1, 5], src: [], note: 'تختم الانفطار بيوم الدين، يوم لا تملك نفس لنفس شيئًا. وتبدأ المطففين بالويل لمن ينقصون الكيل والميزان، وتذكّرهم بأنهم مبعوثون ليوم عظيم.' },
  { from: 83, topicLink: 'يتواصل موضوع يوم القيامة وكتاب الأعمال، فتعود الانشقاق إلى أحداث ذلك اليوم بعد ضحك المجرمين من المؤمنين. ويتصل التكذيب: «لا يؤمنون». ويُعطى الكتاب بالأيمان أو من وراء الظهر.', tail: [34, 36], head: [1, 4], src: [], note: 'تختم المطففين بالمؤمنين يضحكون من الكفار. وتبدأ الانشقاق بأحداث ذلك اليوم من جديد: السماء تنشق والأرض تمد.' },
  { from: 84, topicLink: 'تختم الانشقاق بتكذيب الكافرين وبشارتهم بالعذاب، وتبدأ البروج بالقسم ثم بأصحاب الأخدود. ويتصل القسم والتكذيب.', tail: [22, 25], head: [1, 4], src: [], note: 'تختم الانشقاق بتكذيب الكفار وبشارتهم بعذاب أليم، وللمؤمنين أجر غير ممنون. وتبدأ البروج بالقسم ثم بقتل أصحاب الأخدود، مثالًا لمن عذّب المؤمنين.' },
  { from: 85, topicLink: 'بعد القسم بالسماء ذات البروج يأتي القسم بالسماء والطارق. ويتكرر ذكر القرآن وكيد المكذبين، وتنتقل الأدلة من الأمثال إلى خلق الإنسان.', tail: [19, 22], head: [1, 4], src: [], note: 'تنتهي البروج بقرآن مجيد في لوح محفوظ. وتبدأ الطارق بالقسم بالسماء وبأن على كل نفس حافظًا، فيتصل الحفظ في الموضعين.' },
  { from: 86, topicLink: 'تنتهي الطارق بكيد المكذبين وبأن القرآن قول فصل، وتنتقل الأعلى إلى التسبيح وخلق الله وتذكير النبي ﷺ. وتشترك السورتان في آيات الخلق.', tail: [13, 17], head: [1, 4], src: [], note: 'تنتهي الطارق بأن القرآن قول فصل وبإمهال الكافرين رويدًا. وتبدأ الأعلى بأمر بالتسبيح، فينتقل الكلام من الكافرين إلى العبادة.' },
  { from: 87, topicLink: 'تنتهي الأعلى بتفضيل الآخرة على الدنيا، وتفصّل الغاشية بعدها حال الوجوه. ويتصل التذكير «فذكّر» وآيات الخلق في الإبل.', tail: [16, 19], head: [1, 4], src: [], note: 'تنتهي الأعلى بأن الآخرة خير وأبقى. وتبدأ الغاشية بسؤال عن حديث الغاشية ووصف وجوه يومئذ خاشعة، فتفصّل ما ذُكر عن الآخرة.' },
  { from: 88, topicLink: 'تنتهي الغاشية بالإياب والحساب، وتأتي الفجر بالأقسام وهلاك عاد وثمود وفرعون. والمشترك يوم القيامة وجزاء الجنة.', tail: [22, 26], head: [1, 5], src: [], note: 'تنتهي الغاشية بأن إلى الله إياب الناس وعليه حسابهم. وتبدأ الفجر بأقسام ثم بسؤال: هل في ذلك قسم لذي حجر؟' },
  { from: 89, topicLink: 'بعد جزاء النفس المطمئنة في الفجر يأتي في البلد القسم وخلق الإنسان في كبد والإطعام وفك الرقبة. وتشترك السورتان في الأقسام وطبع الإنسان والإنفاق والجزاء.', tail: [27, 30], head: [1, 4], src: [], note: 'تختم الفجر بالنفس المطمئنة تُدعى إلى جنة الله. وتبدأ البلد بالقسم ثم بأن الإنسان خُلق في كبد، فيقابل الاطمئنانَ الكبدُ.' },
  { from: 90, topicLink: 'تنتهي البلد بانقسام الناس إلى أصحاب الميمنة والمشأمة، وتفصّل الشمس فلاح من زكّى النفس وخيبة من دسّاها. وتشترك السورتان في الأقسام وطبع الإنسان والتزكية والصبر.', tail: [17, 20], head: [1, 4], src: [], note: 'تنتهي البلد بأصحاب الميمنة وأصحاب المشأمة. وتبدأ الشمس بأقسام متتابعة.' },
  { from: 91, topicLink: 'يتصل القسم بالليل والنهار، وينتقل الكلام من مثال ثمود إلى الإنفاق والتقوى مقابل البخل.', tail: [11, 15], head: [1, 4], src: [], note: 'تنتهي الشمس بعقر ثمود الناقة. وتبدأ الليل بالقسم بالليل والنهار.' },
  { from: 92, topicLink: 'بعد وعد المتقي بالرضا يأتي وعد النبي ﷺ بالعطاء والرضا في الضحى. ويتكرر القسم بالليل وأمر اليتيم والسائل مقابل البخل.', tail: [17, 21], head: [1, 5], src: [], shared: [['ولسوف', 21, 5]], note: 'تنتهي الليل بأن الأتقى يؤتي ماله يتزكى «ولسوف يرضى». وتبدأ الضحى بالقسم ثم بوعد النبي ﷺ «ولسوف يعطيك ربك فترضى»، فتتكرر «ولسوف» والرضا.' },
  { from: 93, topicLink: 'تتابع الشرح تعداد نعم الله على النبي ﷺ بعد الضحى، فالموضوع واحد: التسلية والامتنان.', tail: [7, 11], head: [1, 4], src: [ALUKAH_DUHA], note: 'تعدّد الضحى نعم الله على النبي ﷺ: ضالًّا فهدى وعائلًا فأغنى، وتختم بالأمر بالتحدث بنعمة الرب. وتتابع الشرح تعداد النعم: شرح الصدر ووضع الوزر ورفع الذكر.' },
  { from: 94, topicLink: 'تنتهي الشرح بوعد اليسر والتوجه إلى الله، وتبدأ التين بالقسم وأحسن تقويم والبلد الأمين. ويتصل الامتنان بالنعم.', tail: [5, 8], head: [1, 4], src: [], note: 'تنتهي الشرح بأن مع العسر يسرًا وبالأمر بالرغبة إلى الله. وتبدأ التين بالقسم بالتين والزيتون وطور سينين والبلد الأمين.' },
  { from: 95, topicLink: 'يتصل خلق الإنسان في أحسن تقويم بخلقه من علق، ويتصل طبع الإنسان: «أسفل سافلين» و«إن الإنسان ليطغى».', tail: [4, 8], head: [1, 5], src: [], shared: [['الانسن', 4, 2]], note: 'تذكر التين خلق الإنسان في أحسن تقويم وتختم بأحكم الحاكمين. وتبدأ العلق بالأمر بالقراءة وبخلق الإنسان من علق، فتتكرر «الإنسان» والخلق.' },
  { from: 96, topicLink: 'تبدأ العلق بالقراءة، وتذكر القدر ليلة إنزال القرآن، فيجتمعان على موضوع الوحي.', tail: [15, 19], head: [1, 3], src: [], note: 'تنتهي العلق بالأمر بالسجود والاقتراب. وتبدأ القدر بأن الله أنزله في ليلة القدر، والضمير للقرآن الذي افتتحت العلق بالأمر بقراءته.' },
  { from: 97, topicLink: 'بعد نزول القرآن في ليلة القدر يأتي الرسول الذي يتلو الصحف المطهرة في البينة. فالموضوع المشترك الوحي.', tail: [3, 5], head: [1, 3], src: [], note: 'القدر: ليلة نزول القرآن وتنزّل الملائكة والروح. البينة: رسول من الله يتلو صحفًا مطهرة فيها كتب قيّمة.' },
  { from: 98, topicLink: 'تنتهي البينة بجزاء الكافرين والمؤمنين، وتعرض الزلزلة مشهد الجزاء بعد زلزلة الأرض.', tail: [6, 8], head: [4, 8], src: [], note: 'تنتهي البينة بجزاء الكافرين في نار جهنم وجزاء المؤمنين في جنات عدن. وتعرض الزلزلة مشهد الجزاء: يصدر الناس ليروا أعمالهم، فمن يعمل مثقال ذرة خيرًا يره.' },
  { from: 99, topicLink: 'من الأعمال التي يراها الناس في الزلزلة إلى جحود الإنسان في العاديات. والمشترك طبع الإنسان وأحداث ذلك اليوم.', tail: [6, 8], head: [9, 11], src: [], shared: [['يوميذ', 6, 11]], note: 'تذكر الزلزلة أن الناس «يومئذ» يصدرون ليروا أعمالهم. وتختم العاديات بأن ربهم بهم «يومئذ» لخبير، بعد أن بُعثر ما في القبور وحُصّل ما في الصدور.' },
  { from: 100, topicLink: 'بعد بعثرة القبور وتحصيل ما في الصدور تأتي القارعة بأهوال القيامة والميزان.', tail: [9, 11], head: [1, 5], src: [], note: 'تنتهي العاديات ببعثرة القبور وتحصيل ما في الصدور. وتبدأ القارعة بالقارعة وما أدراك ما القارعة، يوم يكون الناس كالفراش المبثوث.' },
  { from: 101, topicLink: 'من ثقل الموازين وخفتها وهاوية النار إلى الانشغال بالتكاثر، والتحذير بالجحيم والسؤال عن النعيم.', tail: [7, 11], head: [1, 5], src: [], note: 'تنتهي القارعة بمن خفّت موازينه فأمه هاوية، نار حامية. وتبدأ التكاثر بأن التكاثر ألهاهم حتى زاروا المقابر، ثم يكرر الوعيد: «كلا سوف تعلمون».' },
  { from: 102, topicLink: 'ينتقل الكلام من الانشغال بالدنيا إلى الخسر، والاستثناء بالإيمان والعمل الصالح والتواصي.', tail: [5, 8], head: [1, 3], src: [], note: 'تنتهي التكاثر بالسؤال يومئذ عن النعيم. وتبدأ العصر بالقسم بالعصر وبأن الإنسان في خسر إلا من آمن وعمل صالحًا وتواصى بالحق والصبر.' },
  { from: 103, topicLink: 'بعد خسر الإنسان تأتي الهمزة بنموذج لمن اغتر بماله: «يحسب أن ماله أخلده»، فيتصل طبع الإنسان.', tail: [2, 3], head: [1, 4], src: [], note: 'تحكم العصر بالخسر على الإنسان إلا من استثنت. وتبدأ الهمزة بالويل لكل همزة لمزة جمع مالًا وعدّده، نموذجًا لمن لم يدخل في الاستثناء.' },
  { from: 104, topicLink: 'تنتهي الهمزة بنار الحطمة، وتبدأ الفيل بمثال من الهلاك الدنيوي للمعتدين. فلا يشتركان في موضوع من قائمتنا، وينتقل الكلام من العقاب في الآخرة إلى العقاب في الدنيا.', tail: [5, 9], head: [1, 5], src: [], note: 'تنتهي الهمزة بنار موصدة على من ظن أن ماله أخلده. وتبدأ الفيل بمثال من الهلاك الدنيوي: أصحاب الفيل جعلهم الله كعصف مأكول.' },
  { from: 105, topicLink: 'تنتهي الفيل بهلاك من قصدوا الكعبة وتبدأ قريش بنعمة الأمن والإطعام. لا موضوع مشترك في قائمتنا، والصلة في القول المنقول في الخطوة.', tail: [1, 5], head: [1, 4], src: [KSU_QURAYSH], note: 'قال الفراء: «هذه السورة متصلة بالسورة الأولى»، فما فُعل بأصحاب الفيل نعمة على قريش «لإيلاف قريش». وفي مصحف أبيّ بن كعب لا فصل بينهما. وعند القرطبي هي «مفصولة عن التي قبلها في المصحف الإمام» بسطر البسملة، فالصلة مناسبة بين سورتين لا دمج.' },
  { from: 106, topicLink: 'بعد الأمر بعبادة رب هذا البيت يأتي من يسهو عن صلاته ويراءي، فتتصل العبادة ويتقابل شكر النعمة وجحودها.', tail: [3, 4], head: [1, 3], src: [], note: 'تذكّر قريش بأن الله أطعمهم من جوع. وتبدأ الماعون بمن يكذب بالدين ولا يحض على طعام المسكين، فيقابل الإطعامَ تركُ الحض عليه.' },
  { from: 107, topicLink: 'تقابل الكوثر خصال الماعون: العطاء مقابل البخل، والصلاة مقابل تركها.', tail: [4, 7], head: [1, 3], src: [MTAFSIR_SUYUTI], note: 'نقل أحد المشاركين في الملتقى عن السيوطي أن الكوثر «كالمقابلة للتي قبلها»، وأن السابقة ذكرت أربعة أمور: البخل وترك الصلاة والرياء ومنع الماعون. فيقابلها: «إنا أعطيناك» للبخل، و«فصل» أي دُم عليها لترك الصلاة، و«لربك» للرياء، و«وانحر» لمنع الماعون.' },
  { from: 108, topicLink: 'بعد الأمر بالصلاة لله والنحر يأتي الأمر بالمفاصلة في العبادة. وتشترك السورتان في خطاب النبي ﷺ والتوحيد وذكر المكذبين: «شانئك» و«الكافرون».', tail: [2, 3], head: [1, 3], src: [], note: 'تأمر الكوثر النبي ﷺ أن يصلي لربه وينحر. وتبدأ الكافرون بإعلان عبادته وحده دون ما يعبدون: «لا أعبد ما تعبدون».' },
  { from: 109, topicLink: 'بعد البراءة من الشرك يأتي النصر ودخول الناس في دين الله. ويتصل خطاب النبي ﷺ والتوحيد: «لا أعبد» و«فسبح بحمد ربك».', tail: [5, 6], head: [1, 3], src: [], shared: [['دين', 6, 2]], note: 'تختم الكافرون بـ«لكم دينكم ولي دين». وتصف النصر دخول الناس «في دين الله» أفواجًا، فتتكرر «دين» في الآيتين.' },
  { from: 110, topicLink: 'بعد بشارة النبي ﷺ بالنصر يأتي هلاك من عاداه، فيتقابل النصر والخسران.', tail: [1, 3], head: [1, 3], src: [], note: 'تذكر النصر نصر الله والفتح ودخول الناس في الدين. وتذكر المسد هلاك أبي لهب الذي عادى النبي ﷺ وأن ماله لم يغن عنه.' },
  { from: 111, topicLink: 'ينتقل الكلام من هلاك المعادي إلى التوحيد الخالص، ولا تشتركان في موضوع من قائمتنا.', tail: [3, 5], head: [1, 4], src: [], note: 'تنتهي المسد بنار ذات لهب لأبي لهب وامرأته. وتبدأ الإخلاص بـ«قل هو الله أحد»، فينتقل الكلام من هلاك المعادي إلى وصف الله وحده.' },
  { from: 112, topicLink: 'بعد التوحيد تأتي الاستعاذة بالله، وتبدأ السورتان بـ«قل» أمرًا للنبي ﷺ.', tail: [1, 4], head: [1, 2], src: [], shared: [['قل', 1, 1]], note: 'تفتتح الإخلاص بـ«قل هو الله أحد» وتفتتح الفلق بـ«قل أعوذ». بعد وصف الله تأتي الاستعاذة به.' },
  { from: 113, topicLink: 'تنتقل الاستعاذة من شر الخلق إلى شر الوسواس، ويتكرر الأمر «قل» والاعتصام بالرب.', tail: [1, 5], head: [1, 4], src: [MTAFSIR_MUAWWIDHATAYN], shared: [['قل اعوذ برب', 1, 1], ['من شر', 2, 4]], note: 'في الفلق استعاذة من شر ما خلق، ويمثّل له المصدر بظلمة الليل والسحرة والحاسدين. وفي الناس استعاذة من الوسواس الذي يوسوس في القلوب، ويذكر المصدر معه شياطين الإنس والجن. ومن ملاحظتنا لا من المصدر أن السورتين تتفقان في «قل أعوذ برب» وفي «من شر».' },
];

