export const sharedThemes = (table: Record<number, SurahTopics>, n: number) =>
  table[n].topics.map(([t]) => t).filter(t => table[n + 1]?.topics.some(([u]) => u === t));

export type OrderData = Data & { counts: Record<string, number> };
export type Line = { ayah: number; text: string; slots?: Record<number, number> };
export type TopicView = { theme: string; detail: string };
export type ChipView = Surah & { focus?: string; topics: TopicView[] };
export type HopView = { hop: Hop; from: Surah; to: Surah; tail: Line[]; head: Line[]; words: string[]; common: string[] };

export function buildOrder({ names, ayat }: OrderData): { chips: ChipView[]; hops: HopView[] } {
  const surah = (number: number): Surah => ({ number, name: names[number] ?? '', plain: plainName(names[number] ?? '') });
  const lines = (n: number, [lo, hi]: Range, shared: NonNullable<Hop['shared']>, side: 1 | 2): Line[] =>
    Array.from({ length: hi - lo + 1 }, (_, k) => {
      const text = ayat[`${n}:${lo + k}`];
      if (text === undefined) throw new Error(`${n}:${lo + k} is missing from the data`);
      const w = ayahWords(text, false);
      const slots: Record<number, number> = {};
      shared.forEach((s, i) => {
        if (s[side] === lo + k) for (const j of resolve(w.norm, [s[0], 'third'])) slots[j] = i + 1;
      });
      return { ayah: lo + k, text: w.display.join(' '), slots: Object.keys(slots).length ? slots : undefined };
    });
  const hops = HOPS.map(hop => {
    const [tail, head] = [lines(hop.from, hop.tail, hop.shared ?? [], 1), lines(hop.from + 1, hop.head, hop.shared ?? [], 2)];
    const words = (hop.shared ?? []).map((_, i) => {
      const line = tail.find(l => l.slots && Object.values(l.slots).includes(i + 1))!;
      return line.text.split(' ').filter((_, j) => line.slots![j] === i + 1).join(' ');
    });
    return { hop, from: surah(hop.from), to: surah(hop.from + 1), tail, head, words, common: sharedThemes(TOPICS, hop.from) };
  });
  const [lo, hi] = [HOPS[0].from, HOPS[HOPS.length - 1].from + 1];
  const chips = Array.from({ length: hi - lo + 1 }, (_, k) => {
    const n = lo + k;
    const { focus, topics } = TOPICS[n];
    return { ...surah(n), focus, topics: topics.map(([theme, detail]) => ({ theme, detail })) };
  });
  return { chips, hops };
}
